cy.title().then(title => {
  const passed = Boolean(title && title.trim().length > 0);
  addResult('Perceivable', 'Titre de page (<title>)', 5, passed, title || 'vide');
});

cy.get('img:visible').then($imgs => {
  let missing = 0;
  $imgs.each((i, el) => {
    const $el = Cypress.$(el);
    if ($el.attr('role') === 'presentation' || $el.attr('role') === 'none') return;
    if ($el.width() <= 1 && $el.height() <= 1) return;
    if ($el.attr('alt') === undefined) missing++;
  });
  const passed = missing === 0;
  addResult('Perceivable', 'Images avec attribut alt', 5, passed, passed ? `${$imgs.length} images OK` : `${missing} image(s) sans alt`);
});

cy.injectAxe();
cy.checkA11y(null, {
  runOnly: ['color-contrast']
}, violations => {
  const count = violations.length ? violations[0].nodes.length : 0;
  const passed = count === 0;
  addResult('Perceivable', 'Contraste des couleurs WCAG AA', 8, passed, passed ? 'Aucun problème' : `${count} élément(s) avec contraste insuffisant`);
}, true);

cy.get('body').then($body => {
