cy.get('a:visible').first().focus().then($el => {
  const outlineStyle = $el.css('outline-style');
  const outlineWidth = parseFloat($el.css('outline-width'));
  const boxShadow = $el.css('box-shadow');
  const hasFocusIndicator = outlineStyle !== 'none' && outlineWidth > 0 || boxShadow && boxShadow !== 'none';
  addResult('Operable', 'Indicateur de focus visible', 6, hasFocusIndicator, hasFocusIndicator ? 'Focus visible (outline/box-shadow)' : 'Focus non visible');
});

