cy.get('body').then($body => {
  const blink = $body.find('blink, marquee, [style*="animation"]');
  // Filtrer les animations dangereuses (flash > 3/sec)
  const dangerousElements = [];
  blink.each((i, el) => {
    const tag = el.tagName.toLowerCase();
    if (tag === 'blink' || tag === 'marquee') dangerousElements.push(tag);
  });
  const passed = dangerousElements.length === 0;
  addResult('Operable', 'Pas de contenu clignotant dangereux', 3, passed, passed ? 'OK' : `Éléments problématiques: ${dangerousElements.join(', ')}`);
});

let tooSmall = 0;
let total = 0;
cy.get('a:visible, button:visible').each($el => {
  const w = $el.outerWidth();
  const h = $el.outerHeight();
  total++;
  if (w < 24 || h < 24) tooSmall++;
}).then(() => {
  const passed = tooSmall <= Math.ceil(total * 0.1); // tolère 10%
  addResult('Operable', 'Cibles tactiles ≥ 24×24px', 5, passed, `${tooSmall}/${total} cibles trop petites`);
});

cy.get('nav, [role="navigation"]').then($navs => {
  const passed = $navs.length > 0;
  addResult('Operable', 'Navigation cohérente (<nav>)', 4, passed, `${$navs.length} zone(s) de navigation`);
});

let vague = 0;
const vagueTexts = ['cliquez ici', 'click here', 'ici', 'lire la suite', 'en savoir plus', 'more', 'here', 'link'];
cy.get('a:visible').each($a => {
  const text = ($a.text() || '').trim().toLowerCase();
  const ariaLabel = ($a.attr('aria-label') || '').trim().toLowerCase();
  const effectiveText = ariaLabel || text;
  if (vagueTexts.includes(effectiveText)) vague++;
}).then(() => {
  const passed = vague === 0;
  addResult('Understandable', 'Liens explicites (pas de "cliquez ici")', 5, passed, passed ? 'Tous les liens ont un texte explicite' : `${vague} lien(s) vague(s)`);
});

let unlabeled = 0;
let total = 0;
cy.get('body').then($body => {
  $body.find('input:visible, select:visible, textarea:visible').each((i, el) => {
    const $el = Cypress.$(el);
    const type = $el.attr('type');
    if (type === 'hidden' || type === 'submit' || type === 'button') return;
    total++;
    const id = $el.attr('id') || '';
    const hasLabel = id ? $body.find(`label[for="${id}"]`).length > 0 : false;
    const hasAria = Boolean($el.attr('aria-label') || $el.attr('aria-labelledby') || $el.attr('title'));
    if (!hasLabel && !hasAria) unlabeled++;
  });
  const passed = unlabeled === 0;
  addResult('Understandable', 'Champs de formulaire labellisés', 5, passed, `${unlabeled}/${total} champ(s) sans label`);
});

// Vérifie la présence d'attributs aria-invalid, aria-errormessage, ou role="alert"
cy.get('body').then($body => {
  const forms = $body.find('form');
  if (forms.length === 0) {
    addResult('Understandable', 'Messages d\'erreur identifiables', 4, true, 'Pas de formulaire détecté');
  } else {
    // Vérifier que le site a une stratégie d'erreur (aria-invalid ou .error ou role=alert)
    const hasErrorStrategy = $body.find('[aria-invalid], [role="alert"], .fr-error-text, .error-message').length > 0 || $body.find('input[required], input[aria-required]').length > 0;
    addResult('Understandable', 'Messages d\'erreur identifiables', 4, hasErrorStrategy, hasErrorStrategy ? 'Stratégie d\'erreur détectée' : 'Aucune gestion d\'erreur ARIA/HTML5');
  }
});

