cy.get('body').then($body => {
  const inputs = $body.find('input:visible, select:visible, textarea:visible').not('[type="hidden"], [type="submit"], [type="button"]');
  if (inputs.length === 0) {
    addResult('NNG Heuristiques', 'Prévention des erreurs (validation)', 3, true, 'Pas de champs détectés');
  } else {
    let withValidation = 0;
    inputs.each((i, el) => {
      const $el = Cypress.$(el);
      if ($el.attr('required') || $el.attr('pattern') || $el.attr('type') === 'email' || $el.attr('type') === 'number' || $el.attr('minlength') || $el.attr('maxlength') || $el.attr('aria-required')) {
        withValidation++;
      }
    });
    const passed = withValidation > 0 || inputs.length === 0;
    addResult('NNG Heuristiques', 'Prévention des erreurs (validation)', 3, passed, `${withValidation}/${inputs.length} champ(s) avec validation`);
  }
});

cy.get('body').then($body => {
  const inputs = $body.find('input:visible').not('[type="hidden"], [type="submit"], [type="button"]');
  if (inputs.length === 0) {
    addResult('NNG Heuristiques', 'Reconnaissance > rappel (indices visuels)', 3, true, 'Pas de champs');
  } else {
    let withHint = 0;
    inputs.each((i, el) => {
      const $el = Cypress.$(el);
      if ($el.attr('placeholder') || $el.attr('aria-describedby') || $el.attr('title')) withHint++;
    });
    const passed = withHint >= inputs.length * 0.5;
    addResult('NNG Heuristiques', 'Reconnaissance > rappel (indices visuels)', 3, passed, `${withHint}/${inputs.length} champ(s) avec indice`);
  }
});

